using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 bool encounterFixture;bool EncountersEnabled=>!((testing||coopCheckRole!=null)&&!encounterFixture);
 bool InEncounterLot(double x,double z)=>ExpeditionEncounter.InLot(game.World,x,z)||InCampaignLot(x,z);
 void SpawnEncounters(){if(!EncountersEnabled||dungeon!=null)return;for(int i=0;i<ExpeditionEncounter.All.Length;i++){var p=ExpeditionEncounter.Place(game.World,i);if(!NearActiveSurface(Ground(p.X,p.Z),200))continue;string id=$"story/vignette/{game.Save.Seed}/{i}";if(!uniqueObjects.Add(id))continue;double floor=LetterFloor(p.X,p.Z,6,5);var n=new Node3D{Name="Encounter_"+i,Position=new((float)p.X,(float)floor,(float)p.Z)};worldRoot.AddChild(n);props.Add(new(){Id=id,Kind=27,Material=i,Node=n,Position=n.ToGlobal(new Vector3(0,0,3.5f))});DressEncounter(n,i);}SpawnEncounterGuardians();}
 void DressEncounter(Node3D n,int index){var e=ExpeditionEncounter.All[index];int t=e.Theme;var worn=new Color(.34f,.36f,.30f);LetterFoundation(n,n.Position.X,n.Position.Z,n.Position.Y,6,5);LetterRamp(n,n.Position.X,n.Position.Z,n.Position.Y,5,18);
 if(t is 1 or 2 or 3 or 4 or 5){Box(n,new(-5,1.6f,0),new(.2f,3.2f,8),worn,true);Box(n,new(5,1.6f,0),new(.2f,3.2f,8),worn,true);Box(n,new(0,1.6f,-4),new(10,3.2f,.2f),worn,true);Box(n,new(0,3.3f,0),new(10.3f,.18f,8.4f),Wood);}
 if(t==0){EncounterBus(n);EncounterFarmhouse(n);}
 if(t==1){Tube(n,new(-2,0,-1),new(-2,3.4f,-1),.12f,Wood);Tube(n,new(2,0,-1),new(2,3.4f,-1),.12f,Wood);Tube(n,new(-2,3.4f,-1),new(2,3.4f,-1),.12f,Wood);Ellipsoid(n,new(0,2.8f,-1),new(.5f,.45f,.5f),new(.48f,.39f,.20f));Tube(n,new(0,.4f,-1),new(0,2.6f,-1),.012f,Cloth);if(index==3){for(int j=0;j<6;j++)Ellipsoid(n,new(j*.15f-.4f,.9f,-2),new(.08f,.10f,.08f),new(.57f,.47f,.36f));}}
 if(t==2){for(int j=-1;j<=1;j++){Box(n,new(j*2,.65f,-1),new(1.4f,.2f,2.3f),Steel,true);Box(n,new(j*2,.8f,-1),new(1.3f,.14f,2.2f),Cloth);}if(index==2){LetterPerson(n,"TheVet",new(-3,0,-2.7f),false,new(.44f,.49f,.46f));Ellipsoid(n,new(0,1,-1),new(.4f,.15f,.85f),Cloth);}else{for(int j=0;j<4;j++)Tube(n,new(-.5f+j*.3f,.9f,-.3f),new(-.5f+j*.3f,1.5f,-.3f),.015f,Steel);}}
 if(t==3){for(int j=0;j<3;j++){Box(n,new(-3+j*3,1.2f,-2.7f),new(2.2f,.1f,.7f),Steel,true);for(int k=0;k<4;k++)Bevel(n,new(-3.7f+j*3+k*.45f,1.45f,-2.7f),new(.28f,.5f,.3f),Cloth);}Box(n,new(0,.8f,0),new(2,.12f,1.2f),Wood,true);}
 if(t==4){Box(n,new(0,.8f,0),new(7,.12f,1.5f),Wood,true);int seats=index==6?23:2;for(int j=0;j<seats;j++){float x=-3+(j%12)*.53f,z=j<12?-.45f:.45f;Ellipsoid(n,new(x,.89f,z),new(.18f,.015f,.18f),Cloth);StoryPaper(n,new(x,.91f,z));}if(index==6)n.AddChild(new Label3D{Text="COUNSELOR DUTIES / 23 PLACES",Position=new(0,2,-3.8f),FontSize=30,PixelSize=.007f});}
 if(t==5){Box(n,new(-2.7f,1.1f,-2),new(1.5f,2.2f,1),Wood,true);for(int j=0;j<3;j++){var board=Box(n,new(-2.7f,.55f+j*.6f,-1.45f),new(1.7f,.15f,.08f),Wood);board.RotationDegrees=new(0,0,j*7-8);}Box(n,new(1.5f,.75f,-.3f),new(2,.12f,1.4f),Wood,true);if(index==7){Ellipsoid(n,new(1.5f,.96f,-.3f),new(.35f,.16f,.35f),new(.58f,.42f,.28f));n.AddChild(new Label3D{Text="HAPPY 7TH BIRTHDAY, SAM",Position=new(0,2.5f,-3.8f),FontSize=28,PixelSize=.008f});}}
 if(t==6){for(int j=0;j<8;j++)Box(n,new(0,.1f,-j*.8f),new(2.7f,.2f,.75f),Wood,true);for(int j=-1;j<=1;j+=2)Tube(n,new(j*1.3f,-.5f,-3),new(j*1.3f,1,-3),.09f,Wood);Bevel(n,new(2,.4f,0),new(.6f,.8f,.4f),Cloth);}
 if(t==7){for(int j=0;j<4;j++){Tube(n,new(-4+j*2,0,-2),new(-4+j*2,1.2f,-2),.06f,Wood);if(j<3)Tube(n,new(-4+j*2,.7f,-2),new(-2+j*2,.7f,-2),.04f,Wood);}Box(n,new(2,.65f,0),new(1.5f,1.3f,.7f),Wood,true);for(int j=0;j<4;j++)Box(n,new(1.6f+j*.25f,1.1f,-.4f),new(.16f,.4f,.3f),new(.28f,.34f+j*.04f,.32f));}
 if(t==8){Tube(n,new(-2,0,-2),new(-2,6,-2),.07f,Steel);for(int j=1;j<=4;j++)Tube(n,new(-3,j*1.2f,-2),new(-1,j*1.2f,-2),.025f,Steel);Box(n,new(1,.6f,0),new(1.8f,1.2f,1),Steel,true);Box(n,new(1,1.3f,0),new(.7f,.2f,.4f),Ink);}
 if(index==7){var child=new Node3D{Name="FreedSam",Position=new(0,0,-1)};n.AddChild(child);FeverChild(child,false);child.Visible=false;}
 StoryPaper(n,new(0,.58f,3.5f));Box(n,new(0,.28f,3.5f),new(.8f,.55f,.65f),Wood,true);
 }
 void DrawEncounters(){if(CoopClient)foreach(var e in infected.Where(e=>IsEncounterGuardian(e.Id)))TickEncounterGuardian(e,0);foreach(var p in props.Where(p=>p.Kind==27&&p.Material==7)){var child=p.Node.GetNodeOrNull<Node3D>("FreedSam");if(child!=null)child.Visible=game.World.Changes.EncounterChoices.Contains(7);}}
 WorldProp NearEncounter()=>EncountersEnabled&&dungeon==null?props.FirstOrDefault(p=>p.Kind==27&&p.Position.DistanceTo(player.Position+Vector3.Up*.3f)<3):null;
 bool EncounterInteract(){var site=NearEncounter();if(site==null)return false;if(!CoopRequest("encounter","read|"+site.Material))EncounterAction("read|"+site.Material);return true;}
 void EncounterAction(string data){if(CoopClient)return;var parts=data.Split('|');if(parts.Length!=2||!int.TryParse(parts[1],out int i)||i<0||i>=ExpeditionEncounter.All.Length)return;var site=NearEncounter();if(site==null||site.Material!=i)return;var e=ExpeditionEncounter.All[i];if(parts[0]=="choose"&&!game.World.Changes.EncounterChoices.Contains(i)){if(e.Reward==0&&game.Life.Food<1){game.Notice="You need one food portion to leave here.";return;}if(e.Reward==2&&game.Life.Bandages<2){game.Notice="You need two bandages.";return;}if(!game.Change(()=>{if(e.Reward==0)game.Life.Food--;if(e.Reward==2)game.Life.Bandages-=2;if(e.Reward==3)game.Life.Food+=2;if(e.Reward==4)game.Craft.Materials[4]+=3;game.World.Changes.EncounterChoices.Add(i);game.AwardResearch("encounter/"+i,5);}))return;Sound(e.Theme==1?4:2);}else if(parts[0]!="read")return;
 if(parts[0]=="choose"&&(i is 5 or 6))game.Notice=e.After;if(!game.Profile.Journal.Seen.Contains("encounter/"+i))game.Change(()=>game.Profile.Journal.Seen.Add("encounter/"+i));if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopEncounterPage),i);else ShowEncounterPage(i);}
 void ShowEncounterPage(int i){var e=ExpeditionEncounter.All[i];if((i is 5 or 6)&&game.World.Changes.EncounterChoices.Contains(i)){CloseMenu();game.Notice=e.After;return;}var box=Panel(e.Title.ToUpperInvariant());Text(box,e.Clue);if(game.World.Changes.EncounterChoices.Contains(i))Text(box,e.After);else Button(box,e.Action.ToUpperInvariant(),()=>{CloseMenu();if(!CoopRequest("encounter","choose|"+i))EncounterAction("choose|"+i);});Button(box,"LEAVE",CloseMenu);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopEncounterPage(int i){if(CoopClient&&i>=0&&i<ExpeditionEncounter.All.Length)ShowEncounterPage(i);}
 void EncounterJournal(VBoxContainer box){for(int i=0;i<ExpeditionEncounter.All.Length;i++){int copy=i;if(game.Profile.Journal.Seen.Contains("encounter/"+i))Button(box,ExpeditionEncounter.All[i].Title.ToUpperInvariant(),()=>{var page=Panel(ExpeditionEncounter.All[copy].Title);Text(page,ExpeditionEncounter.All[copy].Clue);Button(page,"BACK",CloseMenu);});}}
}
